    const thresholdColor=v=>v===(usage?m.config.critical_value:this.cutoff(m))?'var(--quota-critical)':v===(usage?m.config.warning_value:this.warning(m))?'var(--quota-warning)':null;const levels=usage&&['above','below'].includes(m.config.threshold_mode)?[...new Set([0,m.config.warning_value,m.config.critical_value,scaleMax])].sort((a,b)=>a-b):(usage||zoom)?[0,scaleMax/2,scaleMax]:[...new Set([0,50,this.warning(m),this.cutoff(m),100])].sort((a,b)=>a-b);return `<svg viewBox="0 0 930 265" role="img" aria-label="${esc(this.t(usage?"Observed usage over time":"Quota usage percentage over time"))}">${levels.map(v=>`<line x1="48" x2="868" y1="${yy(v)}" y2="${yy(v)}" stroke="${thresholdColor(v)||'#354054'}" stroke-dasharray="4 5"/><text x="8" y="${yy(v)+4}" fill="${thresholdColor(v)||'#acbad0'}" font-size="12">${this.num(v)}${usage?'':'%'}</text>`).join('')}<path d="${path}" fill="none" stroke="#70dace" stroke-width="2.5"/>${pts.length<500?pts.map(p=>`<circle cx="${x(p.at)}" cy="${yy((usage?p.used:p.percent))}" r="2.5" fill="#70dace"><title>${esc(this.date(p.at))} · ${this.num((usage?p.used:p.percent))}${usage?' '+esc(this.unit(m)):'%'} · ${esc(p.period)}</title></circle>`).join(''):''}<text x="48" y="252" fill="#acbad0" font-size="12">${esc(this.date(start))}</text><text x="868" y="252" text-anchor="end" fill="#acbad0" font-size="12">${esc(this.date(end))}</text></svg><p class="muted">${this.num(pts.length)}${this.t(" saved samples · Lines break at quota resets and measurement gaps. Historical samples remain visible without a fresh measurement.")}</p>`;
