  contentDetail(m){if(m.status==='counter_unavailable')return `<h2>${esc(this.name(m))}</h2><p>${this.counterStatus(m)}</p><p>${this.counterReason(m)}</p>${this.counterNote(m)}${this.graph(m,true)}`;if(m.type==='retired')return this.retiredDetail(m);if(m.provider_signal)return this.providerSignalDetail(m);if(m.type==='reference')return this.policyDetail(m);if(m.type==='metric'&&(this.usageOnly(m)||(['above','below'].includes(m.config?.threshold_mode)&&m.sample)))return this.usageDetail(m);if(m.type==='metric'&&this.reportedEmpty(m))return this.emptyReportDetail(m);if(m.type==='unknown')return `<span class="eyebrow">${this.t("Service coverage")}</span><h2>${esc(m.title)}</h2><span class="badge unknown">${this.t("Quota limit not verified")}</span><div class="empty">${esc(this.unknownReason(m))}<br>${this.t("No usage percentage or quota history is available.")}${m.domain==='google_translate'?`<p><a href="https://www.home-assistant.io/integrations/google_translate/" target="_blank" rel="noopener noreferrer">${this.t("Provider documentation ↗")}</a></p>`:''}</div><dl><dt>${this.t("Integration")}</dt><dd>${esc(m.domain)}</dd><dt>${this.t("Status")}</dt><dd>${m.entry.disabled?this.t("Disabled"):esc(m.entry.state)}</dd><dt>${this.t("Protection")}</dt><dd>${this.t("No quota protection configured")}</dd></dl><p class="muted">${this.t("A cloud connection does not necessarily imply a usage allowance or charge. Check with the provider whether a limit applies.")}</p>`;
    const fresh=this.fresh(m),[tone,label]=this.state(m);return `<span class="eyebrow">${this.t("Quota details")}</span><h2>${esc(this.name(m))}</h2><div class="row"><span class="badge ${tone}">${label}</span><b class="detailvalue ${tone}">${fresh?this.num(m.percent)+'%':this.t("Usage unknown")}</b></div><p class="muted">${esc(this.unit(m))} · ${esc(this.t({rate_limit:"API rate limit",free_allowance:"Free allowance",budget:"Budget"}[m.config.kind]||''))}</p>${!fresh?`<div class="notice">${esc(this.reason(m))}${this.t(" Do not assume zero usage.")}</div>`:''}<div class="detailnumbers"><div>${this.t("Used")}<b>${fresh?this.num(m.used??m.sample.used):this.t("Unknown")}</b></div><div>${this.t("Limit")}<b>${this.num(this.limit(m))}</b></div><div>${this.t("Remaining")}<b>${fresh?this.num(m.remaining):this.t("Unknown")}</b></div></div><div class="row charttools"><h3>${this.t("Usage over time")}</h3><div class="row"><select id="range" aria-label="${esc(this.t("Chart range"))}"><option value="1" ${this.range==='1'?'selected':''}>${this.t("1 hour")}</option><option value="24" ${this.range==='24'?'selected':''}>${this.t("24 hours")}</option><option value="168" ${this.range==='168'?'selected':''}>${this.t("7 days")}</option><option value="all" ${this.range==='all'?'selected':''}>${this.t("All samples")}</option></select><button id="zoom" aria-pressed="${!!this.zoom}">${this.zoom?this.t("Show quota thresholds"):this.t("Focus on usage")}</button></div></div>${this.graph(m)}<dl><dt>${this.t("Quota period")}</dt><dd>${esc(this.period(m))}</dd><dt>${this.t("Last source check")}</dt><dd>${esc(this.date(m.sample?.timestamp))}</dd>${m.last_usage_point?`<dt>${this.t("Last reported activity")}</dt><dd>${esc(this.date(m.last_usage_point))}</dd>`:''}<dt>${this.t("Data source")}</dt><dd>${esc(m.config.source)}</dd><dt>${this.t("Policy")}</dt><dd>${esc(this.coverage(m))}</dd><dt>${this.t("Thresholds")}</dt><dd>${this.alertSummary(m)}<br>${m.config.enforce?`<span class="threshold-critical">${this.t(m.provider_kind==='oracle'?'Oracle power-off at':'Integration cutoff at')} ${this.num(this.cutoff(m))}%</span>`:this.t("No automatic cutoff")}</dd>${m.cutoff_result?`<dt>${this.t("Cutoff result")}</dt><dd>${esc(Object.values(m.cutoff_result).join(', '))}</dd>`:''}</dl>${m.provider_note?`<p class="notice">${esc(this.t(m.provider_note))}</p>`:''}<p class="muted">${this.t("Cutoff applies to mapped Home Assistant integrations. Activity outside Home Assistant continues. Re-enabling after cutoff is manual.")}</p>`;
  }
  providerSignalTile(m){const signal=m.provider_signal;return `<button class="tile ${signal.confirmed?'danger':'pending'}" data-key="${esc(m.key)}"><span class="badge ${signal.confirmed?'danger':'pending'}">${this.t(signal.confirmed?'Provider reports quota exhausted':'Last report · no active alert')}</span><h3>${esc(m.config?this.name(m):m.title)}</h3><p class="detailvalue">${this.t(signal.confirmed?'Monthly calls exhausted':'Last reported monthly exhaustion')}</p><p>${this.t('Next expected monthly reset')}: <b>${esc(signal.expected_reset_date)}</b></p><p class="explain">${this.t(signal.confirmed?'IMOU has reported quota exhaustion. Exact usage and limit are unavailable; cloud actions may fail.':'IMOU previously reported exhausted monthly calls. Waiting for a current provider report.')}</p><div class="tilefoot"><span>${this.t('Further alerts paused')}</span><span>${this.t('Details →')}</span></div></button>`;}
  providerSignalDetail(m){const signal=m.provider_signal;return `<span class="eyebrow">${this.t('Provider repair signal')}</span><h2>${esc(m.config?this.name(m):m.title)}</h2><span class="badge danger">${this.t(signal.confirmed?'Provider reports quota exhausted':'Last report · no active alert')}</span><p class="notice error">${this.t(signal.confirmed?'IMOU has reported quota exhaustion. Exact usage and limit are unavailable; cloud actions may fail.':'IMOU previously reported exhausted monthly calls. Waiting for a current provider report.')}</p><p>${this.t('Add quota or wait for the provider month to reset, then reload the IMOU integration. A reminder email does not stop API calls.')}</p><p class="notice">${this.t('Further alerts paused')} · ${this.t('Next expected monthly reset')}: <b>${esc(signal.expected_reset_date)}</b><br>${this.t('The provider reset time and timezone are unverified. This date is an estimate, not confirmation that quota has recovered.')}</p><dl><dt>${this.t('Source')}</dt><dd>${esc(signal.source)}</dd><dt>${this.t('Detected at')}</dt><dd>${esc(this.date(signal.reported_at))}</dd></dl><p><a class="control" href="/config/integrations/integration/quota_guard">${this.t('Set up IMOU usage')}</a> · <a href="/config/repairs">${this.t('Open Home Assistant Repairs')}</a> · <a href="${esc(signal.resources_url)}" target="_blank" rel="noopener noreferrer">${this.t('Open IMOU My Resources')}</a></p>`;}
