  usageTile(m){const fresh=this.usageFresh(m),[tone,label]=this.state(m);return `<button class="tile ${fresh?tone:'pending'}" data-key="${esc(m.key)}"><div class="tilehead"><span class="badge ${fresh?tone:'pending'}">${fresh?label:this.t('Last usage measurement · stale')}</span></div><h3>${esc(this.name(m))}</h3><p class="sub">${esc(this.unit(m))}</p><div class="value">${this.num(m.sample.used)}<small>${this.t(m.config.measurement==='balance'?'Available credits':'observed')}</small></div><p class="explain">${this.alertSummary(m)}</p>${m.counter?`<p>${this.t('This Home Assistant only · partial day')}</p>`:''}<p>${esc(this.coverage(m))}</p><div class="tilefoot"><span>${this.t('Source checked: ')}${esc(this.date(m.sample.timestamp))}</span><span>${this.t('Details and chart →')}</span></div></button>`;}
  usageDetail(m){if(m.config.measurement==='balance')return this.balanceDetail(m);return `<span class="eyebrow">${this.t('Usage monitoring')}</span><h2>${esc(this.name(m))}</h2><span class="badge ${this.state(m)[0]}">${this.usageFresh(m)?this.state(m)[1]:this.t('Last usage measurement · stale')}</span><p class="detailvalue ${this.usageFresh(m)?this.state(m)[0]:'unavailable'}">${this.num(m.sample.used)} ${esc(this.unit(m))}</p><p class="notice">${this.t('A verified allowance is optional for warning and critical alerts based on measured amounts.')}<br>${this.alertSummary(m)}<br>${esc(this.coverage(m))}</p>${this.counterNote(m)}<p><a class="control" href="/config/integrations/integration/quota_guard">${this.t('Configure warning and critical alerts')}</a></p><div class="row charttools"><h3>${this.t('Observed usage over time')}</h3><select id="range" aria-label="${this.t('Chart range')}">${[['1','1 hour'],['24','24 hours'],['168','7 days'],['all','All samples']].map(([v,label])=>`<option value="${v}" ${this.range===v?'selected':''}>${this.t(label)}</option>`).join('')}</select></div>${this.graph(m,true)}<dl><dt>${this.t('Reporting period')}</dt><dd>${esc(this.period(m))}</dd><dt>${this.t('Last source check')}</dt><dd>${esc(this.date(m.sample.timestamp))}</dd><dt>${this.t('Source')}</dt><dd>${esc(m.config.source)}</dd>${m.observation?`<dt>${this.t('Current observation session started')}</dt><dd>${esc(this.date(m.observation.started_at))}</dd><dt>${this.t('HTTP errors / rate-limited responses')}</dt><dd>${this.num(m.observation.errors)} / ${this.num(m.observation.rate_limited)}</dd>`:''}</dl>${m.provider_note?`<p class="notice">${esc(this.t(m.provider_note))}</p>`:''}${m.policy?`<details><summary>${this.t('Provider limits')}</summary>${this.policyDetail(m)}</details>`:''}`;}
